head.script:
scwin.btn_addTab_onclick = async function(e) {
	await tab_main.addTab(
		"tab_main_1",
		{
			"label": "TAB_1",
			"openAction": "exist"
		},
		{
			"src": "/sample/common_link/tabControl_addTabAwait_WESE-989_(WSQ-5859)_sub.xml",
			"wframe": true
		}
	);

	await tab_main.setSelectedTabIndex(0);
	tab_main.getWindow(0).ipt2.setValue("22");
};

scwin.checkVal = function() {
	return (document.getElementById('tab_main_contents_tab_main_1_body_ipt2') || document.getElementById('mf_tab_main_contents_tab_main_1_body_ipt2')).value == '22';
};
